"""Generated clone installers. Never edit the committed adapter outputs."""
from __future__ import annotations

import json
import re
from string import Template

from ..install.agent_skills_projection import SCHEMA_VERSION, sibling_pack_root
from .host_adapters import HOST_ADAPTERS, host_adapter_manifest


_SH = Template(r'''#!/bin/sh
# Generated by omh docs agent-skills; edit the catalog/producer, not this file.
set -eu
fail() { printf '%s\n' "$$*" >&2; exit 1; }
scope=repo
case $$# in
    0) ;;
    1) [ "$$1" = --user ] || fail 'Usage: install.sh [--user]'; scope=user ;;
    *) fail 'Usage: install.sh [--user]' ;;
esac
base=$$(pwd -P)
if [ "$$scope" = user ]; then
    [ -n "$${HOME:-}" ] || fail 'HOME is required for --user'
    base=$$(CDPATH= cd -- "$$HOME" && pwd -P)
    target="$$base/$user_path"
else
    target="$$base/$repo_path"
fi
source="$$(dirname -- "$$0")/$sh_source"
[ ! -L "$$source" ] || fail 'Symlink source root'
source=$$(CDPATH= cd -- "$$source" && pwd -P)
if command -v sha256sum >/dev/null 2>&1; then
    checksum() { sha256sum "$$@"; }
elif command -v shasum >/dev/null 2>&1; then
    checksum() { shasum -a 256 "$$@"; }
else
    fail 'SHA256 verification requires sha256sum or shasum'
fi
# The receipt is the one inventory: generated beside the pack, pinned by the
# docs gate, and copied verbatim. Accept only the layout the producer emits:
# every line of the "files" block is one "<path>": "<sha256>" row and no row
# sits outside it, so the rows read here are exactly the files a JSON reader
# of the copied receipt will think it owns.
inventory="$$source/$receipt_name"
[ -f "$$inventory" ] || fail 'Missing source inventory'
row='"[A-Za-z0-9._/-]\{1,\}": "[0-9a-f]\{64\}"'
skeleton=$$(sed -e '/^  "files": {$$/,/^  },$$/{' -e "/^    $$row,\$$/d" -e "s/^    $$row\$$/ROW/" -e '}' \
    -e 's/^  "catalog_revision": "[0-9a-f]\{64\}",$$/  "catalog_revision": REV,/' "$$inventory")
[ "$$skeleton" = '{
  "catalog_revision": REV,
  "files": {
ROW
  },
  "schema_version": "$schema_version",
  "target_dirs": [
    "."
  ]
}' ] || fail 'Unexpected source inventory layout'
checksums=$$(sed -n '/^  "files": {$$/,/^  },$$/s/^    "\([^"]*\)": "\([0-9a-f]\{64\}\)",\{0,1\}$$/\2  \1/p' "$$inventory")
paths=$$(printf '%s\n' "$$checksums" | sed 's/^[0-9a-f]*  //')
# Refuse by name, as install.ps1 does, before the order and tree checks: an
# empty, `.` or `..` segment aliases or escapes the destination, and a
# case-variant pair is one file on a case-insensitive destination.
printf '%s\n' "$$paths" | while IFS= read -r path; do
    case /$$path/ in
        *//*|*/./*|*/../*) fail "Unsafe source inventory path: $$path" ;;
    esac
done
folded=$$(printf '%s\n' "$$paths" | sed 'y/ABCDEFGHIJKLMNOPQRSTUVWXYZ/abcdefghijklmnopqrstuvwxyz/' | LC_ALL=C sort)
[ "$$folded" = "$$(printf '%s\n' "$$folded" | LC_ALL=C sort -u)" ] || fail 'Duplicate or case-variant source inventory path'
[ "$$paths" = "$$(printf '%s\n' "$$paths" | LC_ALL=C sort -u)" ] || fail 'Source inventory rows are not sorted and unique'
# Reject extra files and links rather than silently installing an unverified tree.
[ -z "$$(find "$$source" ! -type f ! -type d -print)" ] || fail 'Unsupported source entry (including symlink)'
actual=$$(cd "$$source" && find . -type f ! -path './$receipt_name' -print | LC_ALL=C sort)
expected=$$(printf '%s\n' "$$paths" | while IFS= read -r path; do printf './%s\n' "$$path"; done)
[ "$$actual" = "$$expected" ] || fail 'Source file inventory mismatch'
verify() {
    printf '%s\n' "$$checksums" | (cd "$$1" && checksum -c -) >/dev/null || fail 'Skill digest mismatch'
}
verify "$$source"
# Preflight EVERY target before the first write, including the receipt.
# Do not follow destination links.
printf '%s\n' "$$paths" '$receipt_name' | while IFS= read -r path; do
    current="$$target/$$path"
    while [ "$$current" != "$$base" ]; do
        [ ! -L "$$current" ] || fail "Symlink destination: $$current"
        current=$${current%/*}
        [ -n "$$current" ] || current=/
        [ ! -e "$$current" ] || [ -d "$$current" ] || fail "Not a directory: $$current"
    done
    [ ! -e "$$target/$$path" ] || [ -f "$$target/$$path" ] || fail "Not a file: $$target/$$path"
done
# Support data needs ownership even though ordinary skill bodies are replaceable.
# Use the previous one receipt, never a per-host or duplicate inventory.
printf '%s\n' "$$checksums" | while IFS= read -r row; do
    hash=$${row%% *}; path=$${row#*  }
    case $$path in
        */toolkit/*)
            if [ -f "$$target/$$path" ]; then
                prior=
                if [ -f "$$target/$receipt_name" ]; then
                    prior=$$(awk -v key="\"$$path\":" '$$1 == key {gsub(/[",]/, "", $$2); print $$2}' "$$target/$receipt_name")
                fi
                [ -n "$$prior" ] || prior=$$hash
                actual=$$(checksum "$$target/$$path"); actual=$${actual%% *}
                [ "$$actual" = "$$prior" ] || fail "Foreign/edited support preserved: $$path (move it aside, then rerun)"
            fi ;;
    esac
done
printf '%s\n' "$$paths" | while IFS= read -r path; do
    mkdir -p "$$target/$${path%/*}"
    cp "$$source/$$path" "$$target/$$path"
done
verify "$$target"
cp "$$inventory" "$$target/$receipt_name"
printf 'Installed $host skills in %s\n' "$$target"
# Cursor and opencode load both pack roots, so a second copy is a second set of skills.
[ ! -f "$$base/$sibling_path/$receipt_name" ] || printf 'Warning: %s also holds OMH Agent Skills; Cursor and opencode load both directories and find each skill twice. See docs/AGENT-SKILLS.md#duplicate-copies.\n' "$$base/$sibling_path" >&2
printf '%s\n' "$$paths" | sed 's|/.*||' | LC_ALL=C sort -u
''')

_PS1 = Template(r'''# Generated by omh docs agent-skills; edit the catalog/producer, not this file.
param([switch]$$User)
$$ErrorActionPreference = 'Stop'
# Pinned rather than `Latest`, as in the root install.ps1: this file runs on
# whatever PowerShell the user has, so binding strictness to "newest the host
# knows" would let a future release break an installer nobody edited.
Set-StrictMode -Version 3.0
if ($$args.Count) { throw 'Usage: install.ps1 [-User]' }
$$base = (Get-Location).ProviderPath
if ($$User) {
    $$base = $$env:USERPROFILE
    if (-not $$base) { $$base = $$env:HOME }
    if (-not $$base) { throw 'User profile is required for -User' }
    $$target = Join-Path $$base '$user_path'
} else {
    $$target = Join-Path $$base '$repo_path'
}
$$source = Join-Path $ps_source_parent '$ps_source_leaf'
$$inventory = Join-Path $$source '$receipt_name'
if (-not (Test-Path -LiteralPath $$inventory -PathType Leaf)) { throw 'Missing source inventory' }
$$inventoryPath = (Get-Item -Force -LiteralPath $$inventory).FullName
# The receipt is the one inventory: generated beside the pack, pinned by the
# docs gate, and copied verbatim after every listed file verifies. Accept only
# the exact layout the producer emits, so the rows read here are exactly the
# files any JSON reader of the copied receipt will think it owns; no JSON
# parser decides what duplicate or case-variant keys mean.
$$raw = [IO.File]::ReadAllText($$inventoryPath)
$$row = '    "[A-Za-z0-9._/-]+": "[0-9a-f]{64}"'
$$layout = '\A\{\n  "catalog_revision": "[0-9a-f]{64}",\n  "files": \{\n(' + $$row + ',\n)*' + $$row +
    '\n  \},\n  "schema_version": "$schema_version",\n  "target_dirs": \[\n    "\."\n  \]\n\}\n\z'
if ($$raw -cnotmatch $$layout) { throw 'Unexpected source inventory layout' }
$$entries = @([regex]::Matches($$raw, '(?m)^    "([^"]+)": "([0-9a-f]{64})",?$$') |
    ForEach-Object { [PSCustomObject]@{ Path = $$_.Groups[1].Value; Hash = $$_.Groups[2].Value } })
$$seen = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
foreach ($$entry in $$entries) {
    $$segments = $$entry.Path.Split('/')
    if ($$entry.Path -cnotmatch '\A[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*\z' -or
            $$segments -contains '.' -or $$segments -contains '..') {
        throw "Unsafe source inventory path: $$($$entry.Path)"
    }
    if (-not $$seen.Add($$entry.Path)) { throw "Duplicate source inventory path: $$($$entry.Path)" }
}
function Assert-NoLink([string]$$Path, [string]$$Boundary) {
    $$current = $$Path
    while ($$current -and $$current -ne $$Boundary) {
        if (Test-Path -LiteralPath $$current) {
            $$item = Get-Item -Force -LiteralPath $$current
            if ($$item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
                throw "Reparse-point path: $$current"
            }
        }
        $$current = Split-Path -Parent $$current
    }
}
function Assert-DirectoryParents([string]$$Path, [string]$$Boundary) {
    $$current = Split-Path -Parent $$Path
    while ($$current) {
        if ((Test-Path -LiteralPath $$current) -and -not (Test-Path -LiteralPath $$current -PathType Container)) {
            throw "Not a directory: $$current"
        }
        if ($$current -eq $$Boundary) { break }
        $$current = Split-Path -Parent $$current
    }
}
Assert-NoLink $$source (Split-Path -Parent $$source)
$$items = @(Get-ChildItem -Force -Recurse -LiteralPath $$source)
foreach ($$item in $$items) {
    if ($$item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
        throw "Reparse-point source: $$($$item.FullName)"
    }
}
# Compare path sets, not counts: a swapped or aliased row must not pass.
$$prefix = (Get-Item -Force -LiteralPath $$source).FullName.TrimEnd('\', '/').Length + 1
[string[]]$$actual = @($$items | Where-Object { -not $$_.PSIsContainer -and $$_.FullName -ne $$inventoryPath } |
    ForEach-Object { $$_.FullName.Substring($$prefix).Replace('\', '/') })
[string[]]$$expected = @($$entries.Path)
[Array]::Sort($$actual, [StringComparer]::Ordinal)
[Array]::Sort($$expected, [StringComparer]::Ordinal)
if (($$actual -join "`n") -cne ($$expected -join "`n")) { throw 'Source file inventory mismatch' }
function Assert-Digests([string]$$Root) {
    foreach ($$entry in $$entries) {
        $$path = Join-Path $$Root $$entry.Path
        if (-not (Test-Path -LiteralPath $$path -PathType Leaf)) { throw "Missing skill: $$path" }
        if ((Get-FileHash -LiteralPath $$path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $$entry.Hash) {
            throw "Skill digest mismatch: $$path"
        }
    }
}
Assert-Digests $$source
# Preflight the receipt as well as every copied file before any write.
foreach ($$relative in (@($$entries.Path) + '$receipt_name')) {
    $$path = Join-Path $$target $$relative
    Assert-NoLink $$path $$base
    Assert-DirectoryParents $$path $$base
    if ((Test-Path -LiteralPath $$path) -and -not (Test-Path -LiteralPath $$path -PathType Leaf)) {
        throw "Not a file: $$path"
    }
}
$$previous = @{}
$$receipt = Join-Path $$target '$receipt_name'
if (Test-Path -LiteralPath $$receipt -PathType Leaf) {
    foreach ($$match in [regex]::Matches([IO.File]::ReadAllText($$receipt), '(?m)^    "([^"]+)": "([0-9a-f]{64})",?$$')) {
        $$previous[$$match.Groups[1].Value] = $$match.Groups[2].Value
    }
}
foreach ($$entry in $$entries) {
    $$path = Join-Path $$target $$entry.Path
    if ($$entry.Path.Contains('/toolkit/') -and (Test-Path -LiteralPath $$path -PathType Leaf)) {
        $$prior = $$entry.Hash
        if ($$previous.ContainsKey($$entry.Path)) { $$prior = $$previous[$$entry.Path] }
        if ((Get-FileHash -LiteralPath $$path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $$prior) {
            throw "Foreign/edited support preserved: $$path (move it aside, then rerun)"
        }
    }
}
foreach ($$entry in $$entries) {
    $$path = Join-Path $$target $$entry.Path
    [IO.Directory]::CreateDirectory((Split-Path -Parent $$path)) | Out-Null
    [IO.File]::Copy((Join-Path $$source $$entry.Path), $$path, $$true)
}
Assert-Digests $$target
[IO.File]::Copy($$inventory, (Join-Path $$target '$receipt_name'), $$true)
Write-Output "Installed $host skills in $$target"
# Cursor and opencode load both pack roots, so a second copy is a second set of skills.
$$sibling = Join-Path $$base '$sibling_path'
if (Test-Path -LiteralPath (Join-Path $$sibling '$receipt_name') -PathType Leaf) {
    [Console]::Error.WriteLine("Warning: $$sibling also holds OMH Agent Skills; Cursor and opencode load both directories and find each skill twice. See docs/AGENT-SKILLS.md#duplicate-copies.")
}
$$skills = [Collections.Generic.SortedSet[string]]::new([StringComparer]::Ordinal)
foreach ($$entry in $$entries) { [void]$$skills.Add($$entry.Path.Split('/')[0]) }
$$skills
''')


def _source_fields(host: str, source: str) -> dict[str, str]:
    if source == "agent-skills":
        return {"sh_source": "../agent-skills", "ps_source_parent": "(Split-Path -Parent $PSScriptRoot)",
                "ps_source_leaf": "agent-skills"}
    if source.count("/") != 1 or source.split("/")[0] != f".{host}":
        raise ValueError(f"{host}: an adapter's own pack must sit beside its installers, not at {source}")
    leaf = source.split("/")[1]
    return {"sh_source": leaf, "ps_source_parent": "$PSScriptRoot", "ps_source_leaf": leaf}


def host_pack_tree(files: dict[str, str]) -> dict[str, str]:
    """Each host-owned pack (today the Claude copy) with its receipt, keyed from the checkout root."""
    from ..install.agent_skills_projection import MANIFEST_NAME, agent_skills_manifest
    from .host_adapters import host_pack_files

    result: dict[str, str] = {}
    for adapter in HOST_ADAPTERS:
        if adapter.source == "agent-skills":
            continue
        pack = host_pack_files(adapter.host, files)
        result.update({f"{adapter.source}/{relative}": content for relative, content in pack.items()})
        result[f"{adapter.source}/{MANIFEST_NAME}"] = (
            json.dumps(agent_skills_manifest(pack), indent=2, sort_keys=True) + "\n"
        )
    return result


def host_adapter_files(files: dict[str, str]) -> dict[str, str]:
    """All 18 committed files derive from the host rows alone; none carries a file digest."""
    # The scripts accept only these paths; JSON would escape others, and a
    # `.`/`..` segment would alias or escape the destination.
    unsafe = sorted(path for path in files if not re.fullmatch(r"[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)*", path)
                    or any(part in (".", "..") for part in path.split("/")))
    if unsafe:
        raise ValueError(f"Agent Skills paths the clone installers cannot read: {unsafe}")
    result = {}
    for adapter in HOST_ADAPTERS:
        manifest = host_adapter_manifest(adapter.host, files)
        fields = {
            "host": manifest["host"],
            "receipt_name": manifest["inventory"],
            "schema_version": SCHEMA_VERSION,
            "repo_path": manifest["targets"]["repo"],
            "user_path": manifest["targets"]["user"],
            "sibling_path": sibling_pack_root(manifest["targets"]["repo"]),
            # Script-relative source: `../agent-skills`, or a pack beside the script.
            **_source_fields(adapter.host, manifest["source"]),
        }
        result[f".{adapter.host}/install.sh"] = _SH.substitute(fields)
        result[f".{adapter.host}/install.ps1"] = _PS1.substitute(fields)
        result[f".{adapter.host}/manifest.json"] = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    return result
